package com.bct.ngtpa.apiservice.adapter.in.web.controller;import com.bct.ngtpa.apiservice.adapter.in.web.auth.login.*;import com.bct.ngtpa.apiservice.adapter.in.web.auth.login.dto.LoginWorkflowResultResponse;import com.bct.ngtpa.apiservice.adapter.in.web.auth.login.dto.LoginOtpVerifyDataResponse;
import com.bct.ngtpa.apiservice.adapter.in.web.auth.login.dto.LoginOtpVerifyRequest;
import com.bct.ngtpa.apiservice.adapter.in.web.auth.login.mapper.LoginOtpVerifyWebMapper;import com.bct.ngtpa.apiservice.adapter.in.web.auth.registration.config.AuthFlowCookieWriter;import com.bct.ngtpa.apiservice.adapter.in.web.response.MutationResponse;import com.bct.ngtpa.apiservice.application.dto.workflow.*;import com.bct.ngtpa.apiservice.application.port.in.VerifyLoginOtpUseCase;import com.bct.ngtpa.apiservice.application.usecase.auth.login.otp.verify.*;import org.springframework.http.*;import org.springframework.http.server.reactive.ServerHttpResponse;import org.springframework.web.bind.annotation.*;import reactor.core.publisher.Mono;
@RestController @RequestMapping("/api/v1/auth/login/otp") public final class AuthLoginOtpVerifyController {private final VerifyLoginOtpUseCase useCase;private final LoginOtpVerifyWebMapper mapper;private final AuthFlowCookieWriter cookies;public AuthLoginOtpVerifyController(VerifyLoginOtpUseCase u,LoginOtpVerifyWebMapper m,AuthFlowCookieWriter c){useCase=u;mapper=m;cookies=c;}@PostMapping("/verify") public Mono<ResponseEntity<MutationResponse<LoginWorkflowResultResponse<LoginOtpVerifyDataResponse>>>> verify(@RequestBody(required=false) LoginOtpVerifyRequest request,@CookieValue(name="auth_flow_sid",required=false) String session,@RequestHeader(name="X-XSRF-TOKEN",required=false) String csrf,@RequestHeader(name="Idempotency-Key",required=false) String idem,@RequestHeader(name="X-Request-Id",required=false) String requestId,@RequestHeader(name="Accept-Language",required=false) String lang,@RequestHeader(name="Origin",required=false) String origin,@RequestHeader(name="Referer",required=false) String referer,ServerHttpResponse response){if(text(requestId))response.getHeaders().set("X-Request-Id",requestId.trim());if(!text(session))return just(LoginErrorKey.AUTH_FLOW_INVALID.value(),"PAGE");if(!text(csrf))return just(LoginErrorKey.CSRF_INVALID.value(),"PAGE");if(!text(idem))return just(SharedWorkflowErrorKey.IDEMPOTENCY_MISSING.value(),"Idempotency-Key");if(request==null||!text(request.code()))return just(LoginErrorKey.OTP_REQUIRED.value(),"otpCode");try{return useCase.verify(new VerifyLoginOtpCommand(session.trim(),csrf.trim(),request.code().trim(),idem.trim(),clean(origin),clean(referer),clean(lang),clean(requestId))).map(r->{if(r.clearAuthFlowCookie())cookies.clearAuthFlowCookie(response);return LoginHttpResponses.toResponse(mapper.toMutationResponse(r));});}catch(RuntimeException e){return just(LoginErrorKey.REQUEST_INVALID.value(),"PAGE");}}private Mono<ResponseEntity<MutationResponse<LoginWorkflowResultResponse<LoginOtpVerifyDataResponse>>>> just(String code,String target){return Mono.just(LoginHttpResponses.toResponse(mapper.missing(code,target)));}private boolean text(String v){return v!=null&&!v.isBlank();}private String clean(String v){return text(v)?v.trim():null;}}
